<?php declare(strict_types=1);
$columnSetup=$table['columns']??array_map(static fn(array $col):array=>array_replace($col,['name'=>$freeText($col['name'])]),\Kulturhus\Verein\FreeTables::DEFAULT_COLUMNS);
$columnPosted=in_array(input($_POST,'action'),['free-configure','free-create'],true);
if($columnPosted){$columnSetup=[];foreach(arrayInput($_POST,'column_names')as$i=>$name)$columnSetup[]=['name'=>$name,'type'=>arrayInput($_POST,'column_types')[$i]??'text'];}
?>
<form method="post" class="card settings-form"><?= csrf().hidden('action',$table?'free-configure':'free-create').hidden('sheet',$table['id']??'').hidden('version',$columnPosted?input($_POST,'version'):($table['version']??0)) ?><h2><?= e($freeText($table?'Spalten und Listentitel anpassen':'Aufgabenliste anlegen')) ?></h2><label><?= e($freeText('Titel')) ?><input class="form-control" name="title" value="<?= e($columnPosted?input($_POST,'title'):($table['title']??$freeText('Aufgabenliste'))) ?>" required maxlength="120"></label><p><?= e($freeText('Spaltennamen und Typen sind frei anpassbar. „Wer“ kann einen Namen oder ein Team enthalten. Einheiten können frei eingegeben werden. Formelspalten rechnen mit = und zum Beispiel [A]*[B] in derselben Zeile. Zellverknüpfungen übernehmen genau einen Zellverweis. Vorhandene Werte werden nicht automatisch in Berechnungen umgedeutet. Bei anderen Typänderungen müssen die Werte zum neuen Typ passen.')) ?></p><div class="table-scroll" tabindex="0" role="region" aria-label="<?= e($freeText('Listenzeilen, bei Bedarf seitlich scrollen')) ?>"><table class="table"><thead><tr><th><?= e($freeText('Spaltenname')) ?></th><th><?= e($freeText('Werte')) ?></th></tr></thead><tbody><?php for($i=0;$i<20;$i++):$col=$columnSetup[$i]??['name'=>'','type'=>'text']; ?><tr <?= $i>=max(6,count($columnSetup))?'data-free-column-extra':'' ?> data-free-column><td><span aria-hidden="true"><?= chr(65+$i) ?> · </span><input class="form-control" aria-label="<?= e($freeText('Spalte ').($i+1)) ?>" name="column_names[]" value="<?= e($col['name']) ?>" maxlength="80"></td><td><select class="form-control" aria-label="<?= e($freeText('Zelltyp ').($i+1)) ?>" name="column_types[]"><?php foreach(\Kulturhus\Verein\FreeTables::TYPES as $key=>$label): ?><option value="<?= $key ?>" <?= $col['type']===$key?'selected':'' ?>><?= e($freeText($label)) ?></option><?php endforeach ?></select></td></tr><?php endfor ?></tbody></table></div><div class="actions"><button type="button" class="btn btn-outline theme-secondary secondary" data-free-add-column hidden><?= e($freeText('+ Spalte hinzufügen')) ?></button><button class="btn btn-solid theme-primary"><?= e($freeText($table?'Änderungen speichern':'Liste speichern')) ?></button></div><p class="muted"><?= e($freeText('Bis zu 20 Spalten. Bestehende Spalten werden nicht gelöscht; zusätzliche Spalten starten mit leeren Werten.')) ?></p></form><script defer src="free-tables.js?v=4"></script>
